// Generated by `opennextjs-cloudflare build` before Wrangler bundles this file.
// @ts-expect-error `.open-next/worker.js` does not exist until that build runs.
import generatedWorker from './.open-next/worker.js';
import {
  consumeScheduledJobs,
  dispatchScheduledCron,
  type ScheduledCronEnv,
  type ScheduledQueueMessage,
} from './src/workers/dispatch-scheduled-cron';

const handler = generatedWorker as {
  fetch(request: Request, env: unknown, ctx: unknown): Promise<Response>;
};

interface ScheduledController {
  cron: string;
  scheduledTime: number;
}

interface ScheduledBatch {
  messages: readonly ScheduledQueueMessage[];
}

/**
 * OpenNext's generated worker only exports `fetch`. Cron Triggers invoke
 * `scheduled()`, so this entry re-exports fetch and dispatches each cron.
 * Wrangler runs `opennextjs-cloudflare build` before bundling this file.
 */
const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    return handler.fetch(request, env, ctx);
  },

  async scheduled(controller: ScheduledController, env: ScheduledCronEnv) {
    await dispatchScheduledCron({
      cron: controller.cron,
      scheduledTime: controller.scheduledTime,
      env,
    });
  },

  async queue(batch: ScheduledBatch, env: ScheduledCronEnv, ctx: unknown) {
    await consumeScheduledJobs({
      messages: batch.messages,
      env,
      fetchHandler: (request) => handler.fetch(request, env, ctx),
    });
  },
};

export default worker;
